// Final bounded SDK boundary observations: ten new cases, no prior inventory.
#define main unusedPointwiseReferenceMain
#include "../metafile-pointwise-effects-reference-2026-10-27/PointwiseEffectsReference.cpp"
#undef main
#include <sstream>
struct BoundaryCase {
    std::string name,atlasName;
    REAL radius=3,amount=0;
    bool blur=false,expand=false;
    int frame()const{return blur?64:32;}
    void describe(std::ostream& out)const {
        out<<",\"source\":"<<json(name)<<",\"family\":"<<json(blur?"blur":"sharpen")<<",\"atlas\":"<<json(atlasName)<<",\"emf\":"<<json(name+".emf")<<",\"sourceWidth\":32,\"sourceHeight\":32,\"parameters\":{\"radius\":"<<radius;
        if(blur)out<<",\"expandEdge\":"<<(expand?"true":"false");else out<<",\"amount\":"<<amount;
        out<<"},\"recordSourceRect\":"<<(blur?"[4.25,6.5,17.5,18.25]":"[0,0,32,32]")<<",\"recordImageMatrix\":"<<(blur?"[1,0,0,1,16,16]":"[1,0,0,1,0,0]")<<",\"recordFrameWidth\":"<<frame()<<",\"recordFrameHeight\":"<<frame()<<",\"directROI\":null";
    }
};
static std::vector<BoundaryCase> boundaryCases(){std::vector<BoundaryCase> cases;for(const auto& name:{"step","asymmetric"})for(REAL amount:{12.5f,37.5f,75.f,99.f})cases.push_back({std::string("sharpen-")+name+"-a"+std::to_string(int(amount*10)),name,3,amount,false,false});for(bool expand:{false,true})cases.push_back({std::string("blur-fractional-crop-e")+(expand?"1":"0"),"asymmetric",2,0,true,expand});if(cases.size()!=10)throw std::runtime_error("boundary inventory changed");return cases;}
static Color boundaryColor(const std::string& name,UINT x,UINT y){if(name=="step")return Color(255,x<16?0:255,y<11?31:223,x+y<23?240:17);return Color(255,BYTE(11*x+53*y),BYTE(43*x+7*y),BYTE(19*x+37*y));}
static std::unique_ptr<Bitmap> boundaryAtlas(const std::string& name){auto result=std::make_unique<Bitmap>(32,32,PixelFormat32bppARGB);check(result->GetLastStatus(),"source allocation");check(result->SetResolution(96,96),"source DPI");for(UINT y=0;y<32;++y)for(UINT x=0;x<32;++x)check(result->SetPixel(x,y,boundaryColor(name,x,y)),"source pixel");return result;}
template<class Body>static void boundaryEffect(const BoundaryCase& c,Body&& body){if(c.blur){BlurParams p{c.radius,c.expand?TRUE:FALSE};Blur e;body(e,e.SetParameters(&p));}else{SharpenParams p{c.radius,c.amount};Sharpen e;body(e,e.SetParameters(&p));}}
static void boundaryAux(Effect& effect,const fs::path& dir,const std::string& stem,std::ostream& out){UINT size=effect.GetAuxDataSize();out<<",\"auxBytes\":"<<size;if(size>1024*1024)throw std::runtime_error("auxiliary bound");if(size&&effect.GetAuxData()){auto data=file(dir/(stem+".aux"),true);data.write(static_cast<const char*>(effect.GetAuxData()),size);out<<",\"aux\":"<<json(stem+".aux");}}
static void boundaryRecord(const BoundaryCase& c,Effect& e,const fs::path& dir,std::ostream& out){ScreenDC screen;Metafile image((dir/(c.name+".emf")).c_str(),screen.value,RectF(0,0,REAL(c.frame()),REAL(c.frame())),MetafileFrameUnitPixel,EmfTypeEmfPlusOnly,L"Original SDK tiny spatial boundary");Status s=image.GetLastStatus();out<<",\"recordCreateStatus\":"<<s;if(s!=Ok)return;Graphics g(&image);check(g.GetLastStatus(),"record graphics");check(g.SetPageUnit(UnitPixel),"record units");check(g.SetCompositingMode(CompositingModeSourceCopy),"record compositing");check(g.Clear(Color(0,0,0,0)),"record clear");auto input=boundaryAtlas(c.atlasName);RectF source=c.blur?RectF(4.25f,6.5f,17.5f,18.25f):RectF(0,0,32,32);Matrix transform(1,0,0,1,c.blur?16.f:0.f,c.blur?16.f:0.f);check(transform.GetLastStatus(),"record matrix");s=g.DrawImage(input.get(),&source,&transform,&e,nullptr,UnitPixel);out<<",\"recordStatus\":"<<s;}
static void boundaryDirect(const BoundaryCase& c,Effect& effect,const fs::path& dir,const std::string& stem,bool create,std::ostream& out){auto input=boundaryAtlas(c.atlasName);effect.UseAuxData(TRUE);if(!create){Status s=input->ApplyEffect(&effect,nullptr);out<<",\"applyStatus\":"<<s;boundaryAux(effect,dir,stem,out);if(s==Ok)pixels(*input,dir,stem,out);}else{Bitmap* source=input.get();Bitmap* raw=nullptr;RECT bounds{};Status s=Bitmap::ApplyEffect(&source,1,&effect,nullptr,&bounds,&raw);std::unique_ptr<Bitmap> result(raw);out<<",\"applyStatus\":"<<s<<",\"outputRect\":["<<bounds.left<<','<<bounds.top<<','<<bounds.right<<','<<bounds.bottom<<']';boundaryAux(effect,dir,stem,out);if(s==Ok){if(!result)throw std::runtime_error("null successful output");pixels(*result,dir,stem,out);}}}
static void boundaryReplay(const BoundaryCase& c,const fs::path& dir,const std::string& prefix,std::ostream& out){Bitmap image((dir/(c.name+".emf")).c_str(),FALSE);Status s=image.GetLastStatus();out<<",\"bitmapLoadStatus\":"<<s;if(s!=Ok)return;UINT w=image.GetWidth(),h=image.GetHeight();check(image.GetLastStatus(),"intrinsic dimensions");if(!w||!h||w>128||h>128)throw std::runtime_error("replay dimension bound");out<<",\"intrinsicWidth\":"<<w<<",\"intrinsicHeight\":"<<h<<",\"expectedSize\":"<<(w==UINT(c.frame())&&h==UINT(c.frame())?"true":"false")<<",\"intrinsic\":{\"name\":"<<json(prefix+c.name+"-intrinsic");pixels(image,dir,prefix+c.name+"-intrinsic",out);out<<'}';Bitmap target(w,h,PixelFormat32bppARGB);check(target.GetLastStatus(),"replay allocation");check(target.SetResolution(96,96),"replay DPI");{Graphics g(&target);check(g.Clear(Color(0,0,0,0)),"replay clear");check(g.SetCompositingMode(CompositingModeSourceCopy),"replay compositing");check(g.SetInterpolationMode(InterpolationModeDefault),"Picture interpolation");check(g.SetPixelOffsetMode(PixelOffsetModeHalf),"Picture pixel offset");ImageAttributes attributes;check(attributes.SetWrapMode(WrapModeTileFlipXY),"Picture wrap");s=g.DrawImage(&image,Rect(0,0,INT(w),INT(h)),0,0,INT(w),INT(h),UnitPixel,&attributes);}out<<",\"drawStatus\":"<<s;if(s==Ok)pixels(target,dir,prefix+c.name,out);}
int main(int argc,char** argv){if(argc!=3)return 2;try{const std::string mode=argv[1];if(mode!="generate"&&mode!="direct-v1"&&mode!="replay"&&mode!="replay-v1")return 2;bool v1=mode=="direct-v1"||mode=="replay-v1";Startup startup(v1?1:2);findPNGEncoder();fs::path dir=fs::absolute(argv[2]);fs::create_directories(dir);auto inventory=boundaryCases();auto out=file(dir/(mode+".json"));wchar_t module[32768]{};DWORD length=GetModuleFileNameW(GetModuleHandleW(L"gdiplus.dll"),module,32768);if(!length||length>=32768)throw std::runtime_error("cannot identify GDI+");out<<"{\"platform\":\"native Windows GDI+\",\"startupVersion\":"<<(v1?1:2)<<",\"gdiplusModule\":"<<json(fs::path(module).u8string())<<",\"mode\":"<<json(mode)<<",\"caseCount\":10,\"format\":\"straight RGBA row-major top-left\",\"atlases\":[";bool first=true;
for(const auto& name:{"step","asymmetric"}){if(!first)out<<',';first=false;out<<"{\"name\":"<<json(name);if(mode=="generate"){auto image=boundaryAtlas(name);pixels(*image,dir,std::string("atlas-")+name,out);auto data=file(dir/(std::string("atlas-")+name+"-requested.rgba"),true);for(UINT y=0;y<32;++y)for(UINT x=0;x<32;++x){Color c=boundaryColor(name,x,y);BYTE p[]={c.GetR(),c.GetG(),c.GetB(),c.GetA()};data.write(reinterpret_cast<const char*>(p),4);}}out<<'}';}out<<"],\"cases\":[";first=true;bool failed=false;
for(const auto& c:inventory){if(!first)out<<',';first=false;std::string prefix=mode=="generate"?"":mode+"-";out<<"{\"name\":"<<json(prefix+c.name);c.describe(out);std::ostringstream detail;try{if(mode=="generate"||mode=="direct-v1"){if(mode=="generate")boundaryEffect(c,[&](auto& e,Status s){detail<<",\"recordSetParametersStatus\":"<<s;if(s==Ok)boundaryRecord(c,e,dir,detail);});detail<<",\"direct\":{\"name\":"<<json(prefix+c.name);boundaryEffect(c,[&](auto& e,Status s){detail<<",\"setParametersStatus\":"<<s;if(s==Ok)boundaryDirect(c,e,dir,prefix+c.name,false,detail);});detail<<"},\"created\":{\"name\":"<<json(prefix+"created-"+c.name);boundaryEffect(c,[&](auto& e,Status s){detail<<",\"setParametersStatus\":"<<s;if(s==Ok)boundaryDirect(c,e,dir,prefix+"created-"+c.name,true,detail);});detail<<'}';}else boundaryReplay(c,dir,prefix,detail);}catch(const std::exception& error){detail.str("");detail.clear();detail<<",\"error\":"<<json(error.what());failed=true;}out<<detail.str()<<'}';out.flush();}out<<"]}\n";out.close();return failed?1:0;
}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
